import {calculate,dateKey,DEFAULTS,normalizeSettings,normalizeGoal,paydayInfo,calendarMonth,toggleDate,makeBackup,parseBackup} from './calc.mjs';
const desktop=!!window.__TAURI__;let previousResult=null;let preferences={milestones:true,reminder:false};try{preferences={...preferences,...JSON.parse(localStorage.getItem('salary-cheer-preferences')||'{}')};}catch{}
const $=id=>document.getElementById(id),defaults={amount:15000,period:'month',start:'09:00',end:'18:00',days:[1,2,3,4,5],breakEnabled:false,breakStart:'12:00',breakEnd:'13:00',off:[],extra:[],payday:10};
let settings={...defaults},goal={name:'请自己喝杯咖啡',price:25},saved=false,tab='month',hidden=false,quoteIndex=0;
try{const raw=localStorage.getItem('salary-cheer-v1');if(raw){const parsed=normalizeSettings(JSON.parse(raw));settings=parsed;saved=true;}const g=JSON.parse(localStorage.getItem('salary-cheer-goal'));if(g)goal=normalizeGoal(g);hidden=localStorage.getItem('salary-cheer-hidden')==='true';}catch{}
