const quotes=['工资在涨，快乐也不要落下。','你不是在消磨时间，是在攒下一次出发。','每一份小小的积累，都在认真地奔向你。','工作只是生活的一部分，记得把快乐留给自己。','今天也辛苦啦，下班后的时间属于你。','慢慢来，喜欢的生活正在路上。'];
function toast(message){$('toast').textContent=message;$('toast').style.opacity=1;setTimeout(()=>$('toast').style.opacity=0,2600);}
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{toast('浏览器无法保存设置，本次会话仍可使用');return false;}}
function privacy(){document.body.classList.toggle('hidden-money',hidden);$('privacy').textContent=hidden?'◎':'◉';$('privacy').setAttribute('aria-label',hidden?'显示金额':'隐藏金额');$('privacy').title=hidden?'显示金额':'隐藏金额';}
function render(){const now=new Date(),r=calculate(settings,now);$('date-label').textContent=now.toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'});$('clock').textContent=now.toLocaleTimeString('zh-CN',{hour12:false});$('example').hidden=saved;$('status').textContent=r.status;$('earned').textContent=r.earned.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});$('percentage').textContent=(r.progress*100).toFixed(1)+'%';$('progress-fill').style.width=r.progress*100+'%';$('progress').setAttribute('aria-valuenow',(r.progress*100).toFixed(1));$('daily').textContent=money(r.daily);$('second').textContent=money(r.second,4);$('minute').textContent=money(r.minute);$('hour').textContent=money(r.hour);$('start-label').textContent=settings.start+' 上班';$('end-label').textContent=settings.end+' 下班';
 const pay=paydayInfo(settings.payday,now);$('payday-days').textContent=pay.days===0?'今天到账日':pay.days+' 天';$('payday-date').textContent=pay.date+' · 不自动顺延假期';checkMilestones(r);
 $('earning-note').textContent=r.status==='休息日'?'今天休息，把时间留给自己。':r.status==='已下班'?'今日的努力已到账，好好享受生活。':r.status==='还没上班'?'还没到上班时间，先给自己充个电。':r.status==='午休充电中'?'不计薪休息中，收入计时暂停。':'每一秒，都在向小目标靠近';
 const t=Math.ceil(r.remaining),h=Math.floor(t/3600),m=Math.floor(t%3600/60),s=t%60;$('timer').innerHTML=`${String(h).padStart(2,'0')}<span>:</span>${String(m).padStart(2,'0')}<span>:</span>${String(s).padStart(2,'0')}`;$('count-caption').textContent=!r.active?'今天不用上班，好好休息':r.status==='已下班'?'今天的任务完成，快乐下班！':r.status==='还没上班'?'距离今天下班，还有':'距离快乐下班，还有';$('shift-info').textContent=`${settings.start} — ${settings.end}${settings.end<settings.start?' 次日':''} · 每周 ${settings.days.length} 天`;
 const monthly=tab==='month',earned=monthly?r.monthEarned:r.weekEarned,target=monthly?r.monthTarget:r.weekTarget;$('period-earned').textContent=money(earned);$('period-target').textContent=money(target);$('workdays').textContent=`${monthly?'本月':'本周'} ${monthly?r.monthDays:r.weekDays} 个工作日`;$('period-fill').style.width=(target?Math.min(100,earned/target*100):0)+'%';$('goal-name').textContent=goal.name;$('goal-price').textContent=money(goal.price)+' / 目标';const count=Math.floor(r.earned/goal.price);$('goal-message').textContent=count>0?`已赚到 ${count} 份小快乐 ✓`:`再赚 ${money(Math.max(0,goal.price-r.earned))}，就实现啦`;$('goal-fill').style.width=Math.min(100,r.earned/goal.price*100)+'%';$('goal-desc').textContent=count>0?'今天的努力，值得给自己一点奖励。':'努力也值得一点甜。';
}
function showSettings(){for(const key of ['amount','start','end','breakStart','breakEnd','payday'])$(key).value=settings[key];document.querySelector(`[name=period][value=${settings.period}]`).checked=true;$('breakEnabled').checked=settings.breakEnabled;$('break-fields').hidden=!settings.breakEnabled;$('off').value=settings.off.join(', ');$('extra').value=settings.extra.join(', ');document.querySelectorAll('[name=weekday]').forEach(el=>el.checked=settings.days.includes(+el.value));$('form-error').textContent='';$('milestones').checked=preferences.milestones;$('reminder').checked=preferences.reminder;$('settings').showModal();}
$('days').innerHTML=[1,2,3,4,5,6,0].map((d,i)=>`<label><input type="checkbox" name="weekday" value="${d}"><span>${['一','二','三','四','五','六','日'][i]}</span></label>`).join('');
for(const id of ['settings-top','settings-side','setup-example'])$(id).onclick=showSettings;
for(const el of document.querySelectorAll('[data-close]'))el.onclick=()=>$(el.dataset.close).close();
for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close();}});
$('breakEnabled').onchange=e=>$('break-fields').hidden=!e.target.checked;
const parseDates=value=>{const dates=value.split(/[,，\s]+/).filter(Boolean);for(const t of dates){const d=new Date(t+'T12:00:00');if(!/^\d{4}-\d{2}-\d{2}$/.test(t)||Number.isNaN(+d)||dateKey(d)!==t)throw Error('日期请用 YYYY-MM-DD 格式，并填写真实日期');}return [...new Set(dates)];};
$('settings-form').onsubmit=e=>{e.preventDefault();try{const next={amount:+$('amount').value,payday:+$('payday').value,period:document.querySelector('[name=period]:checked').value,start:$('start').value,end:$('end').value,days:[...document.querySelectorAll('[name=weekday]:checked')].map(el=>+el.value),breakEnabled:$('breakEnabled').checked,breakStart:$('breakStart').value,breakEnd:$('breakEnd').value,off:parseDates($('off').value),extra:parseDates($('extra').value)};calculate(next);settings=normalizeSettings(next);preferences={milestones:$('milestones').checked,reminder:$('reminder').checked};persist('salary-cheer-preferences',preferences);previousResult=null;saved=true;const stored=persist('salary-cheer-v1',settings);$('settings').close();render();if(stored)toast('设置已保存，开始积攒小快乐');}catch(error){$('form-error').textContent=error.message;}};
$('privacy').onclick=()=>{hidden=!hidden;persist('salary-cheer-hidden',hidden);privacy();};
$('month-tab').onclick=()=>{tab='month';$('month-tab').classList.add('selected');$('week-tab').classList.remove('selected');render();};$('week-tab').onclick=()=>{tab='week';$('week-tab').classList.add('selected');$('month-tab').classList.remove('selected');render();};
$('new-quote').onclick=()=>{$('quote').textContent=quotes[++quoteIndex%quotes.length];};$('method').onclick=()=>$('info').showModal();$('edit-goal').onclick=()=>{$('goal-title').value=goal.name;$('goal-value').value=goal.price;$('goal-dialog').showModal();};$('goal-form').onsubmit=e=>{e.preventDefault();const name=$('goal-title').value.trim();if(!name){$('goal-title').setCustomValidity('请填写小目标');$('goal-title').reportValidity();return;}goal=normalizeGoal({name,price:+$('goal-value').value});previousResult=null;persist('salary-cheer-goal',goal);$('goal-dialog').close();render();};$('goal-title').oninput=()=>$('goal-title').setCustomValidity('');
$('timezone').textContent='设备时区 · '+Intl.DateTimeFormat().resolvedOptions().timeZone+' ｜ 收入为估算';

function checkMilestones(r){if(saved&&previousResult&&previousResult.shiftDate===r.shiftDate){if(preferences.milestones&&Math.floor(r.earned/goal.price)>Math.floor(previousResult.earned/goal.price)){toast('小目标达成！今天的努力值得一点奖励 ☕');const card=document.querySelector('.income');card.classList.remove('milestone-celebrate');void card.offsetWidth;card.classList.add('milestone-celebrate');}if(desktop&&preferences.reminder&&r.status==='已下班'&&previousResult.status!=='已下班'&&Date.now()-r.shiftEnd<300000){window.__TAURI__.core.invoke('notify_shift').catch(()=>toast('通知未发送，请检查系统通知权限'));}}previousResult=r;}
let calendarDate=new Date(),calendarDraft=null;
function renderCalendar(){const y=calendarDate.getFullYear(),m=calendarDate.getMonth();$('calendar-title').textContent=`${y} 年 ${m+1} 月`;$('calendar-grid').replaceChildren();for(const cell of calendarMonth(calendarDraft,y,m)){const b=document.createElement('button');b.type='button';b.disabled=!cell.key;b.className=[cell.working?'work':'',cell.adjusted?'adjusted':'',cell.today?'today':''].join(' ');if(cell.key){b.textContent=cell.day;const small=document.createElement('small');small.textContent=cell.working?'班':'休';b.append(small);b.setAttribute('aria-label',cell.key+' '+(cell.working?'上班':'休假'));b.onclick=()=>{calendarDraft=toggleDate(calendarDraft,cell.key);renderCalendar();};}$('calendar-grid').append(b);}}
function openCalendar(){calendarDraft=normalizeSettings(settings);calendarDate=new Date();renderCalendar();$('calendar-dialog').showModal();}
$('open-calendar').onclick=openCalendar;$('calendar-side').onclick=openCalendar;
$('prev-month').onclick=()=>{if(calendarDate.getFullYear()>2000||calendarDate.getMonth()>0){calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()-1,1);renderCalendar();}};
$('next-month').onclick=()=>{if(calendarDate.getFullYear()<2100||calendarDate.getMonth()<11){calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+1,1);renderCalendar();}};
$('save-calendar').onclick=()=>{settings=normalizeSettings(calendarDraft);previousResult=null;saved=true;persist('salary-cheer-v1',settings);$('calendar-dialog').close();render();toast('排班已更新，收入已按新排班计算');};
$('compact-toggle').onclick=()=>{const compact=document.body.classList.toggle('compact');$('compact-toggle').textContent=compact?'◱ 完整模式':'◱ 极简模式';};
$('open-widget').hidden=!desktop;$('reminder-label').hidden=!desktop;
$('open-widget').onclick=()=>window.__TAURI__.core.invoke('open_widget').catch(()=>toast('悬浮窗打开失败，请重启应用再试'));
$('export').onclick=async()=>{const text=makeBackup(settings,goal);if(desktop){try{const written=await window.__TAURI__.core.invoke('export_backup',{contents:text});if(written)toast('备份已导出，请妥善保管工资信息');}catch{toast('导出失败，请确认目标目录可写');}return;}const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='salary-cheer-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份包含工资信息，请妥善保管');};
$('import').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>500000)throw Error('备份文件过大');const imported=parseBackup(await file.text());if(!confirm('导入将覆盖此设备的工资、排班和小目标，是否继续？'))return;settings=imported.settings;goal=imported.goal;saved=true;previousResult=null;persist('salary-cheer-v1',settings);persist('salary-cheer-goal',goal);$('settings').close();render();toast('备份已导入');}catch(error){$('form-error').textContent=error.message;}finally{e.target.value='';}};
$('share').onclick=async()=>{const r=calculate(settings,new Date()),text=`今天的工作进度 ${Math.round(r.progress*100)}%，每一秒都有小收获。—— 薪情不错`;if(navigator.share){try{await navigator.share({title:'薪情不错 · 今天的小收获',text});return;}catch(error){if(error.name==='AbortError')return;}}if(navigator.clipboard){try{await navigator.clipboard.writeText(text);toast('分享文案已复制，不含工资金额');return;}catch{}}$('share-text').value=text;$('share-dialog').showModal();};
$('copy-share').onclick=async()=>{const text=$('share-text').value;try{await navigator.clipboard.writeText(text);toast('已复制分享文案');}catch{$('share-text').focus();$('share-text').select();toast('文案已选中，请手动复制');}};
window.addEventListener('storage',e=>{try{if(e.key==='salary-cheer-v1'&&e.newValue){settings=normalizeSettings(JSON.parse(e.newValue));saved=true;previousResult=null;}if(e.key==='salary-cheer-goal'&&e.newValue)goal=normalizeGoal(JSON.parse(e.newValue));if(e.key==='salary-cheer-hidden'){hidden=e.newValue==='true';privacy();}if(e.key==='salary-cheer-preferences'&&e.newValue)preferences={...preferences,...JSON.parse(e.newValue)};render();}catch{}});
